"""M2.1b: text overlay export fidelity, tested on the REAL Pillow renderer (no database, no network).

* the frontend mapper's output (fixture generated by the frontend test) is valid for the real API schema and renders;
* wrapped lines are spaced like the editor's CSS line-height (spacing x FONT SIZE), not ~16 % wider;
* single-line placement is unchanged, so M1 and M2.1a text sits exactly where it did;
* opacity fades the whole element (chip, border, stroke, shadow, glyphs) as CSS opacity does;
* callers that pass no line_spacing (subtitles, lower thirds) are untouched.
"""
import json
from pathlib import Path

import pytest
from PIL import Image

from app.config import settings
from app.schemas.video_export import ExportTextOverlay
from app.services import canvas_render_svc as c

FIXTURE = Path(__file__).resolve().parents[2] / "frontend" / "src" / "pages" / "video-studio-v2" / "export" / "__fixtures__" / "export_text_items.json"


def ink_rows(img: Image.Image, thresh: int = 40) -> list[int]:
    a = img.getchannel("A")
    w, h = a.size
    px = a.load()
    return [y for y in range(h) if any(px[x, y] > thresh for x in range(w))]


def ink_bbox(img: Image.Image, thresh: int = 40):
    a = img.getchannel("A")
    w, h = a.size
    px = a.load()
    xs = [x for x in range(w) for y in range(h) if px[x, y] > thresh]
    ys = ink_rows(img, thresh)
    return (min(xs), min(ys), max(xs) + 1, max(ys) + 1) if xs else None


def line_tops(rows: list[int]) -> list[int]:
    return [r for i, r in enumerate(rows) if i == 0 or r != rows[i - 1] + 1]


def render(text: str, **kw) -> Image.Image:
    args = dict(text=text, box_w=900, font_size=60, color="#ffffff", align="left", bold=False)
    args.update(kw)
    return c.render_styled_text_box(**args)


# ── the contract with the frontend mapper ───────────────────────────────────────────────────────

@pytest.fixture(scope="module")
def items() -> list[dict]:
    assert FIXTURE.exists(), "run the frontend export tests once (UPDATE_EXPORT_FIXTURE=1) to generate the fixture"
    return json.loads(FIXTURE.read_text(encoding="utf-8"))


def test_every_mapped_key_is_a_real_field_of_the_export_schema(items):
    fields = set(ExportTextOverlay.model_fields)
    assert len(items) >= 7
    for it in items:
        assert set(it) <= fields, set(it) - fields
        ExportTextOverlay(**it)                                                          # validates types (font_size is an integer, colours are strings...)


def test_every_mapped_item_renders_at_the_requested_width(items, tmp_path, monkeypatch):
    monkeypatch.setattr(settings, "UPLOAD_DIR", str(tmp_path))
    for it in items:
        model = ExportTextOverlay(**it).model_dump()
        path, w, h = c.render_text_overlay_png(model, 1080, 1920, 1)
        img = Image.open(path)
        assert img.mode == "RGBA" and img.size == (w, h) and h > 0
        box = round(1080 * it["width_pct"] / 100)
        has_shadow = bool(it.get("shadow_color"))
        # the box is exactly the requested width; a shadow only ever adds transparent room to its right/bottom so it can paint outside the box
        assert w == box if not has_shadow else box <= w <= box + round(max(0, it["shadow_offset_x"]) + it["shadow_blur"] * 3) + 1
        assert ink_bbox(img) is not None                                                 # something was drawn


# ── wrapping and line spacing ───────────────────────────────────────────────────────────────────

def test_wrapped_lines_are_spaced_like_the_editors_css_line_height():
    img = render("HH\nHH", line_spacing=1.15, bg_padding=0)
    tops = line_tops(ink_rows(img))
    assert len(tops) == 2
    assert abs((tops[1] - tops[0]) - 60 * 1.15) <= 1.5, tops                             # 69 px = line spacing x font size


def test_a_custom_line_spacing_is_honoured_exactly():
    img = render("HH\nHH", line_spacing=1.6, bg_padding=0)
    tops = line_tops(ink_rows(img))
    assert abs((tops[1] - tops[0]) - 96) <= 1.5, tops


def test_callers_that_pass_no_line_spacing_keep_the_legacy_spacing(monkeypatch):
    """Subtitles and lower thirds never pass line_spacing: their layout must not move."""
    img = render("HH\nHH", bg_padding=0)                                                 # line_spacing=None
    font = c._load_font(60, False)
    ascent, descent = font.getmetrics()
    tops = line_tops(ink_rows(img))
    assert abs((tops[1] - tops[0]) - (ascent + descent) * 1.15) <= 1.5, tops
    assert img.height == round((ascent + descent) * 1.15 * 2)                             # unchanged box height formula


def test_single_line_placement_is_unchanged_so_existing_exports_do_not_move():
    """M1 / M2.1a placement is calibrated to this: ink starts pad + ~0.17 em below the box top."""
    legacy = render("Kuch Bhi Kar Sakti Hai", box_w=1000, bg_padding=8)                  # no line_spacing
    now = render("Kuch Bhi Kar Sakti Hai", box_w=1000, bg_padding=8, line_spacing=1.15)
    a, b = ink_bbox(legacy), ink_bbox(now)
    assert abs(a[1] - b[1]) <= 1 and abs(a[0] - b[0]) <= 1, (a, b)
    assert 17 <= b[1] <= 19, b                                                           # measured 18 px at 60 px with 8 px padding (RENDER_CALIBRATION)


def test_long_text_wraps_inside_its_box_and_never_past_it():
    text = "A much longer line of caption wording that has to wrap onto several lines inside its box"
    img = render(text, box_w=500, font_size=40, line_spacing=1.15, bg_padding=8)
    tops = line_tops(ink_rows(img))
    assert len(tops) >= 3
    assert ink_bbox(img)[2] <= 500 - 8 + 1                                               # nothing ink-wise beyond the inner right edge


# ── alignment ───────────────────────────────────────────────────────────────────────────────────

@pytest.mark.parametrize("align", ["left", "center", "right"])
def test_alignment_places_the_line_within_the_box(align):
    img = render("Hi", box_w=600, align=align, bg_padding=8, line_spacing=1.15)
    x0, _, x1, _ = ink_bbox(img)
    if align == "left":
        assert x0 <= 8 + 8
    elif align == "center":
        assert abs(((x0 + x1) / 2) - 300) <= 4
    else:
        assert 600 - 8 - 8 <= x1 <= 600 - 8 + 1


# ── opacity is a property of the whole element ──────────────────────────────────────────────────

def alpha_max(img: Image.Image) -> int:
    return img.getchannel("A").getextrema()[1]


def test_opacity_one_changes_nothing_about_a_solid_element():
    img = render("Hi", bg_color="#ff0000", bg_opacity=1.0, stroke_color="#00ff00", stroke_width=2, opacity=1.0, line_spacing=1.15)
    assert alpha_max(img) == 255


def test_opacity_fades_the_chip_the_stroke_the_glyphs_and_the_border_together():
    full = render("Hi", bg_color="#ff0000", bg_opacity=1.0, bg_border_color="#0000ff", bg_border_width=3, stroke_color="#00ff00", stroke_width=2, opacity=1.0, line_spacing=1.15)
    half = render("Hi", bg_color="#ff0000", bg_opacity=1.0, bg_border_color="#0000ff", bg_border_width=3, stroke_color="#00ff00", stroke_width=2, opacity=0.5, line_spacing=1.15)
    assert alpha_max(full) == 255 and 126 <= alpha_max(half) <= 129                      # no part of the element stays fully opaque
    fa, ha = full.getchannel("A").load(), half.getchannel("A").load()
    w, h = full.size
    ratios = [ha[x, y] / fa[x, y] for x in range(0, w, 7) for y in range(0, h, 5) if fa[x, y] > 200]
    assert ratios and all(0.48 <= r <= 0.52 for r in ratios)                             # every solid pixel is exactly half as strong


def test_semi_transparent_text_has_no_stroke_colour_bleeding_through_its_fill():
    """The old per-part opacity let the stroke show through a half-transparent fill; group opacity does not."""
    img = render("HH", color="#ffffff", stroke_color="#ff0000", stroke_width=3, opacity=0.5, line_spacing=1.15, bg_padding=10)
    px = img.convert("RGBA").load()
    w, h = img.size
    inner_whites = [px[x, y] for x in range(w) for y in range(h) if px[x, y][3] > 100 and px[x, y][0] > 240 and px[x, y][1] > 240]
    assert inner_whites                                                                  # glyph interior is clean white at half strength, not pink


# ── stroke, shadow, gradient, chip still work ───────────────────────────────────────────────────

def test_stroke_widens_the_silhouette_by_its_width():
    plain = ink_bbox(render("HH", line_spacing=1.15))
    stroked = ink_bbox(render("HH", line_spacing=1.15, stroke_color="#000000", stroke_width=4))
    assert stroked[2] - stroked[0] >= (plain[2] - plain[0]) + 6 and stroked[3] - stroked[1] >= (plain[3] - plain[1]) + 6


def test_shadow_offsets_extra_ink_down_and_right():
    plain = ink_bbox(render("HH", line_spacing=1.15, bg_padding=20))
    shadowed = ink_bbox(render("HH", line_spacing=1.15, bg_padding=20, shadow_color="#000000", shadow_blur=2, shadow_offset_x=10, shadow_offset_y=10))
    assert shadowed[2] >= plain[2] + 6 and shadowed[3] >= plain[3] + 6


def test_gradient_fill_runs_left_to_right():
    img = render("HHHHHH", use_gradient=True, gradient_from="#ff0000", gradient_to="#0000ff", line_spacing=1.15, box_w=700)
    x0, y0, x1, y1 = ink_bbox(img)
    px = img.convert("RGBA").load()
    def at(x):
        return next(px[x, y] for y in range(y0, y1) if px[x, y][3] > 200)
    left, right = at(x0 + 8), at(x1 - 8)
    assert left[0] > right[0] and right[2] > left[2]                                      # redder on the left, bluer on the right (the gradient spans the box, as CSS does)


def test_chip_is_drawn_only_when_asked_for_and_covers_the_box():
    none = render("Hi", line_spacing=1.15)
    chip = render("Hi", line_spacing=1.15, bg_color="#112233", bg_opacity=0.5)
    assert none.getpixel((3, 3))[3] == 0                                                  # no chip: the corner is empty
    assert 120 <= chip.getpixel((chip.width // 2, 3))[3] <= 135                           # chip: half-opaque near the box edge


# ── the editor box model (opt-in: bg_padding_x given) ────────────────────────────────────────────

def white_ink(img: Image.Image):
    """Bounding box of the (near-)white glyph pixels only, so a coloured shadow or stroke never counts as text."""
    px = img.load()
    w, h = img.size
    pts = [(x, y) for y in range(h) for x in range(w) if px[x, y][3] > 200 and px[x, y][0] > 235 and px[x, y][1] > 235 and px[x, y][2] > 235]
    xs, ys = [p[0] for p in pts], [p[1] for p in pts]
    return (min(xs), min(ys), max(xs) + 1, max(ys) + 1)


def test_editor_box_places_ink_at_the_editors_padding():
    """The editor pads 2 px top / 6 px left by default; ink then starts about 0.17 em lower and 0.05 em right (the M2.1a calibration)."""
    img = render("Kuch Bhi Kar Sakti Hai", box_w=1000, bg_padding=2, bg_padding_x=6, line_spacing=1.15)
    x0, y0, _, _ = ink_bbox(img)
    assert 2 + 8 <= y0 <= 2 + 13, y0                                                      # 2 px padding + ~10 px of ascender room at 60 px
    assert 6 <= x0 <= 6 + 6, x0


def test_a_shadow_does_not_move_the_text_in_the_editor_box():
    plain = white_ink(render("Hello World", box_w=800, bg_padding=2, bg_padding_x=6, line_spacing=1.15))
    shadowed = white_ink(render("Hello World", box_w=800, bg_padding=2, bg_padding_x=6, line_spacing=1.15, shadow_color="#2d6bff", shadow_blur=6, shadow_offset_x=6, shadow_offset_y=6))
    assert abs(plain[0] - shadowed[0]) <= 1 and abs(plain[1] - shadowed[1]) <= 1, (plain, shadowed)


def test_a_shadow_still_pushes_the_legacy_layout_exactly_as_before():
    """Legacy mode (no bg_padding_x) is what subtitles and lower thirds use: its text still shifts by half the shadow's size."""
    plain = white_ink(render("Hello World", box_w=800, bg_padding=8, line_spacing=1.15))
    shadowed = white_ink(render("Hello World", box_w=800, bg_padding=8, line_spacing=1.15, shadow_color="#2d6bff", shadow_blur=6, shadow_offset_x=6, shadow_offset_y=6))
    assert shadowed[1] - plain[1] >= 10, (plain, shadowed)                                # round(6 + 6 + 12) / 2 = 12 px lower, as it always was


def test_the_shadow_paints_outside_the_box_by_growing_the_image_not_the_box():
    img = render("Hello", box_w=400, bg_padding=2, bg_padding_x=6, line_spacing=1.15, shadow_color="#000000", shadow_blur=5, shadow_offset_x=8, shadow_offset_y=8)
    plain = render("Hello", box_w=400, bg_padding=2, bg_padding_x=6, line_spacing=1.15)
    assert img.width > plain.width and img.height > plain.height
    assert plain.width == 400


def test_stroke_does_not_change_where_text_wraps_in_the_editor_box():
    text = "alpha bravo charlie delta echo foxtrot golf hotel india"
    def lines(box, stroke, **kw):
        img = render(text, box_w=box, font_size=30, line_spacing=1.15, stroke_color="#ff0000", stroke_width=stroke, **kw)
        return round((img.height - 2 * kw["bg_padding"]) / (30 * 1.15))                   # exact: the box height is line count x line height + padding (strokes would merge ink bands)
    differing = [b for b in range(300, 700, 3) if lines(b, 0, bg_padding=2) != lines(b, 8, bg_padding=2)]
    assert differing, "legacy layout narrows the wrap width by the stroke at some widths (this is what the editor box model removes)"
    for b in differing[:6]:
        assert lines(b, 0, bg_padding=2, bg_padding_x=6) == lines(b, 8, bg_padding=2, bg_padding_x=6), b


def test_a_border_sits_inside_the_box_and_pushes_the_content_in():
    bare = render("Hi", box_w=400, bg_padding=10, bg_padding_x=14, line_spacing=1.15, bg_color="#336699", bg_opacity=1.0)
    bordered = render("Hi", box_w=400, bg_padding=10, bg_padding_x=14, line_spacing=1.15, bg_color="#336699", bg_opacity=1.0, bg_border_color="#ffffff", bg_border_width=5)
    assert bordered.width == bare.width == 400                                            # the box does not grow: border-box
    assert bordered.height == bare.height + 10                                            # content is pushed in: 5 px border top and bottom adds to the box's own height
    assert white_ink(bordered)[0] >= 0
    gb, gu = ink_bbox(render("Hi", box_w=400, bg_padding=10, bg_padding_x=14, line_spacing=1.15, bg_border_color="#ffffff", bg_border_width=5, bg_color="#000000", bg_opacity=0.0)), ink_bbox(bare)
    assert gb is not None                                                                  # a transparent chip still draws its border (border-only overlays)


def test_the_legacy_layout_is_untouched_when_bg_padding_x_is_absent():
    img = render("Hi", box_w=400, bg_padding=8, line_spacing=1.15, shadow_color="#000000", shadow_blur=4, shadow_offset_x=3, shadow_offset_y=3)
    font = c._load_font(60, False)
    expected_h = round(60 * 1.15) + 8 * 2 + round(3 + 3 + 4 * 2)
    assert img.size == (400, expected_h)


def test_editor_box_stroke_is_centred_and_painted_over_the_fill_like_the_browser():
    """-webkit-text-stroke: half the width shows outside the glyph, half cuts into it, and the stroke colour wins where they overlap."""
    kw = dict(box_w=1100, font_size=220, line_spacing=1.15, bg_padding=2, color="#ffffff")               # big enough that the stem keeps a clear white core after a 6 px cut either side
    plain = render("HH", **kw)
    css = render("HH", **kw, bg_padding_x=6, stroke_color="#ff0000", stroke_width=12)
    legacy = render("HH", **kw, stroke_color="#ff0000", stroke_width=12)
    p, c_, lg = ink_bbox(plain), ink_bbox(css), ink_bbox(legacy)
    assert abs((c_[2] - c_[0]) - ((p[2] - p[0]) + 12)) <= 2, (p, c_)                     # silhouette grows by half the stroke on each side (12 in total)
    # the left stem of the first H: walk in from its outer edge along the middle row
    y = (p[1] + p[3]) // 2
    def row(img):
        px = img.convert("RGBA").load()
        return [px[x, y] for x in range(img.width)]
    def first_ink(r):
        return next(i for i, v in enumerate(r) if v[3] > 200)
    rc, rl = row(css), row(legacy)
    x0c, x0l = first_ink(rc), first_ink(rl)
    # css: the ring spans edge-6 .. edge+6 around the glyph edge, so 9 px past the first ink pixel we are in the glyph's red band and 3 px in we are still red (stroke over fill)
    inside_c = rc[x0c + 9]
    inside_l = rl[x0l + 12 + 3]                                                           # legacy: the whole 12 px stroke is OUTSIDE the glyph, so the glyph edge is 12 px in
    assert inside_c[0] > 200 and inside_c[1] < 80, inside_c                               # red where the glyph is cut into by the stroke
    assert inside_l[0] > 200 and inside_l[1] > 200, inside_l                              # legacy: the fill is painted over the stroke, so it stays white
    # and the core of the stem is still the fill colour
    assert any(v[0] > 240 and v[1] > 240 and v[2] > 240 and v[3] > 240 for v in rc[x0c + 6 + 8: x0c + 6 + 22])


def test_editor_box_stroke_leaves_other_callers_alone():
    """Legacy mode (no bg_padding_x) still draws the outside-only stroke with the fill on top."""
    img = render("HH", box_w=700, font_size=120, line_spacing=1.15, bg_padding=10, color="#ffffff", stroke_color="#ff0000", stroke_width=6)
    px = img.convert("RGBA").load()
    assert any(px[x, img.height // 2][1] > 240 for x in range(img.width))                  # white fill is present and on top
